<div class="filter-chips library-tabs"><?php foreach([''=>'Abertas','resolved'=>'Analisadas','all'=>'Todas'] as $value=>$label): ?><a class="chip <?= $status===$value?'selected':'' ?>" href="<?= url('admin',['tab'=>'reports','status'=>$value]) ?>"><?= $label ?></a><?php endforeach ?></div>
<?php if(!$rows): ?><div class="panel admin-empty"><?= icon('shield',32) ?><h2>Nenhum relato neste filtro</h2><p>Denúncias enviadas pelos jogadores entram automaticamente aqui.</p></div><?php endif ?>
<?php foreach($rows as $report): ?><section class="panel"><span class="badge"><?= $report['status']==='open'?'Aberto':'Analisado' ?></span><h2 class="admin-report-title"><?= e($report['title']) ?></h2><p class="small muted">Por <?= e($report['name']) ?> · <?= e($report['created_at']) ?> UTC</p><p class="admin-report-reason"><?= nl2br(e($report['reason'])) ?></p><div class="actions"><a class="button secondary" href="<?= url('game',['id'=>$report['project_id']]) ?>">Inspecionar projeto</a><?php if($report['status']==='open'): ?><form method="post" action="<?= url('admin') ?>"><?= csrf_field() ?><input type="hidden" name="action" value="resolve"><input type="hidden" name="id" value="<?= (int)$report['id'] ?>"><button class="button primary">Marcar como analisado</button></form><?php endif ?></div></section><?php endforeach ?>
